import openpyxl
import datetime
from openpyxl.utils import column_index_from_string

wb = openpyxl.load_workbook('/app/Household_Appliances.xlsx')
ws = wb['Sheet1']

appliances = [
    ('Household Refrigerators', {'current': 'B', 'accumulated': 'C', 'yoy': 'D', 'accum_growth': 'E'}),
    ('Air Conditioners',        {'current': 'F', 'accumulated': 'G', 'yoy': 'H', 'accum_growth': 'I'}),
    ('Household Washing Machines', {'current': 'J', 'accumulated': 'K', 'yoy': 'L', 'accum_growth': 'M'}),
]

# First pass: identify months with at least some data
months_data = {}  # time_val -> {appliance_name -> {field: value}}
for row_num in range(3, ws.max_row + 1):
    time_val = ws.cell(row=row_num, column=1).value
    if not isinstance(time_val, datetime.datetime):
        continue

    month_data = {}
    for name, cols in appliances:
        field_vals = {}
        for field, col_letter in cols.items():
            col_idx = column_index_from_string(col_letter)
            val = ws.cell(row=row_num, column=col_idx).value
            if field in ('yoy', 'accum_growth'):
                field_vals[field] = round(val * 100, 2) if val is not None else None
            else:
                field_vals[field] = val
        month_data[name] = field_vals

    months_data[time_val] = month_data

# Filter months: only include months with at least some data
# "some data" = at least one appliance has at least one non-None field
valid_months = {}
for time_val, month_data in months_data.items():
    has_data = False
    for name, fields in month_data.items():
        for v in fields.values():
            if v is not None:
                has_data = True
                break
        if has_data:
            break
    if has_data:
        valid_months[time_val] = month_data

# Build records sorted descending by date
records = []
for time_val in sorted(valid_months.keys(), reverse=True):
    month_str = time_val.strftime('%Y-%m')
    month_data = valid_months[time_val]
    for name, fields in appliances:
        records.append({
            'time': month_str,
            'appliance': name,
            'current': fields.get('current'),
            'accumulated': fields.get('accumulated'),
            'yoy': fields.get('yoy'),
            'accum_growth': fields.get('accum_growth'),
        })

print(f'Total records: {len(records)}')
print('First 6:')
for r in records[:6]:
    print(r)
print('Last 6:')
for r in records[-6:]:
    print(r)

# Write output
wb_out = openpyxl.Workbook()
ws_out = wb_out.active
ws_out.title = 'Sheet1'

headers = ['Time', 'Appliance types', 'Current Period Sales(Ten Thousand Units)',
           'Accumulated Sales (Ten Thousand Units)', 'Year-on-Year Growth (%)',
           'Accumulated Growth (%)']
for col, header in enumerate(headers, 1):
    ws_out.cell(row=1, column=col, value=header)

for i, rec in enumerate(records, 2):
    ws_out.cell(row=i, column=1, value=rec['time'])
    ws_out.cell(row=i, column=2, value=rec['appliance'])
    ws_out.cell(row=i, column=3, value=rec['current'])
    ws_out.cell(row=i, column=4, value=rec['accumulated'])
    ws_out.cell(row=i, column=5, value=rec['yoy'])
    ws_out.cell(row=i, column=6, value=rec['accum_growth'])

wb_out.save('/app/Processed.xlsx')
print('Saved to /app/Processed.xlsx')
